def countPermutationWindows(nums, m):
    cnt = {}
    good = 0
    ans = 0
    for i, x in enumerate(nums):
        if 1 <= x <= m:
            c = cnt.get(x, 0) + 1
            cnt[x] = c
            if c == 1:
                good += 1
            elif c == 2:
                good -= 1
        if i >= m:
            y = nums[i - m]
            if 1 <= y <= m:
                c = cnt[y]
                cnt[y] = c - 1
                if c == 1:
                    good -= 1
                elif c == 2:
                    good += 1
        if i >= m - 1 and good == m:
            ans += 1
    return ans
